INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000001', '65" 4K OLED Smart TV', 'TV-OLED-65', 189900, '65-inch OLED panel, 4K, HDMI 2.1, built-in streaming apps. Low-latency mode for gaming.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Smart%20Television.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/SamsungSmartTV.JPG"]', 'TV & Home Theatre', 7);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000002', '2.1 Soundbar with Wireless Sub', 'AUD-SBAR-21', 24900, 'Soundbar and wireless subwoofer. HDMI ARC, Bluetooth, optical in. Straightforward setup.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/LG%20LAS260B%20Soundbar.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/SAMSUNG%20SOUNDBAR%20HW-J250.jpg"]', 'Audio', 9);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000003', 'Wireless Noise Cancelling Headphones', 'AUD-ANC-01', 19900, 'Over-ear ANC headphones. Multipoint Bluetooth, ~30hr battery, folds flat.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Jackson%20hedden%20apple%20headphones.jpg"]', 'Audio', 21);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000004', '27" QHD USB-C Monitor', 'MON-QHD-27', 32900, '2560x1440, USB-C video input, height-adjustable stand. Good for desk setups.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Computer%20monitor.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Computer%20Screen%20Monitor.jpg"]', 'Computers & Monitors', 11);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000005', 'HDMI 2.1 Cable 2m', 'CBL-HDMI-2M', 2495, '2m HDMI 2.1 cable. Supports 4K/120Hz, 8K, eARC.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/HDMI%20Cable.JPG","https://commons.wikimedia.org/wiki/Special:Redirect/file/HDMI-Connector.jpg"]', 'Cables & Chargers', 58);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000006', 'USB-C 100W Braided Cable', 'CBL-USBC-100W', 2995, '100W USB-C charging cable, braided sleeve. Works with most laptops and phones.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/HDMI-Connector.jpg"]', 'Cables & Chargers', 44);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000007', 'Wi-Fi 6 Mesh Router 3-Pack', 'NET-MESH-6-3PK', 39900, 'Three-node Wi-Fi 6 mesh system. App setup, guest network, decent coverage for a full house.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Netgear-Nighthawk-AC1900-WiFi-Router.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Linksys-Wireless-G-Router.jpg"]', 'Networking', 10);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000008', 'Video Doorbell 2K', 'SMH-DOOR-2K', 17900, '2K doorbell camera. Two-way audio, motion alerts, night vision, weather resistant.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Ring%20video%20doorbell.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Ring%20Video%20Doorbell%202.jpg"]', 'Smart Home', 17);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000009', 'Smart Plug 4-Pack', 'SMH-PLUG-4PK', 7900, 'App-controlled plugs with scheduling and energy monitoring. Works with Alexa and Google Home.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Smart-plug.jpg"]', 'Smart Home', 26);
